    def ==(other)
      if !other.cursor?
        return false
      end
      if @field_0 != other.field_0
        return false
      end

      true
    end

    # For each variant, we have an `NAME?` method for easily checking
    # whether an instance is that variant.
    
    def cursor?
      instance_of? Start::CURSOR
    end
    
    def current_head?
      instance_of? Start::CURRENT_HEAD
    end
    
