    AcyclicActorsUniffi.validate_actor_id(value)
    @value = value
  end

  def ==(other)
    other.is_a?(self.class) && other.value == @value
  end

  def self.uniffi_check_lower(value)
    unless value.is_a?(self)
      raise TypeError.new "Expected a ActorId instance, got #{value}"
    end
  end

  def self.uniffi_lower(value)
    uniffi_check_lower(value)
    value.value
  end
