    end
  end

  def self.uniffi_lower(value)
    uniffi_check_lower(value)
    value.value
  end
end
  
class PositiveU64
  attr_reader :value

  def initialize(value)
    value = AcyclicActors::uniffi_in_range(value, "u64", 0, 2**64)
    AcyclicActorsUniffi.validate_positive_u64(value)
    @value = value
  end

  def ==(other)
    other.is_a?(self.class) && other.value == @value
  end

  def self.uniffi_check_lower(value)
    unless value.is_a?(self)
      raise TypeError.new "Expected a PositiveU64 instance, got #{value}"
    end
  end

  def self.uniffi_lower(value)
    uniffi_check_lower(value)
    value.value
  end
end

  

  

  
